#!/usr/bin/env sh
# Generated by "cds-guard codeowners --platform azure".
# Creates one required-reviewer branch policy per lock file and then removes the policies an
# earlier run created (their message starts with "cds-guard:"). Approvers must be e-mail
# addresses or Azure DevOps group names. Run after "az login" and "az devops configure --defaults ...".
set -e
: "${REPO_ID:?set REPO_ID to the repository id (az repos show --repository NAME --query id -o tsv)}"
BRANCH=${BRANCH:-main}
OLD=$(az repos policy list --repository-id "$REPO_ID" --branch "$BRANCH" --query "[?type.displayName=='Required reviewers' && settings.message && starts_with(settings.message, 'cds-guard:')].id" -o tsv)
az repos policy required-reviewer create --blocking true --enabled true --branch "$BRANCH" --repository-id "$REPO_ID" --path-filter '/.guard/*;!/.guard/locks/*' --required-reviewer-ids '[Bookshop]\CAP Leads' --message 'cds-guard: guard configuration' --output none
az repos policy required-reviewer create --blocking true --enabled true --branch "$BRANCH" --repository-id "$REPO_ID" --path-filter '/azure-pipelines.yml' --required-reviewer-ids '[Bookshop]\CAP Leads' --message 'cds-guard: guard pipeline' --output none
az repos policy required-reviewer create --blocking true --enabled true --branch "$BRANCH" --repository-id "$REPO_ID" --path-filter '/.guard/locks/pricing-model.lock' --required-reviewer-ids 'alice@acme.example;bob@acme.example' --message 'cds-guard: pricing-model' --output none
az repos policy required-reviewer create --blocking true --enabled true --branch "$BRANCH" --repository-id "$REPO_ID" --path-filter '/.guard/locks/schema-structure.lock' --required-reviewer-ids '[Bookshop]\Backend Team;carol@acme.example' --message 'cds-guard: schema-structure' --output none
az repos policy required-reviewer create --blocking true --enabled true --branch "$BRANCH" --repository-id "$REPO_ID" --path-filter '/.guard/locks/tax-formula.lock' --required-reviewer-ids '[Bookshop]\Finance Approvers' --message 'cds-guard: tax-formula' --output none
az repos policy required-reviewer create --blocking true --enabled true --branch "$BRANCH" --repository-id "$REPO_ID" --path-filter '/.guard/locks/frozen-ui.lock' --required-reviewer-ids '[Bookshop]\CAP Leads' --message 'cds-guard: frozen-ui' --output none
for id in $OLD; do az repos policy delete --id "$id" --yes --output none; done
